     2	  RailError,
     3	  makeSettlementRef,
     4	  type Clock,
     5	  type PaymentRail,
     6	  type PaymentRequest,
     7	  type Quote,
     8	  type RailAuthorization,
     9	  type RailSettlement,
    10	  type Micros,
    11	} from '@mwb/core';
    12	
    13	/**
    14	 * A rail is a backend: quote → authorize → settle, all behind one
    15	 * interface. Field names inside `payload` are intentionally opaque — the
    16	 * specs churn (x402 v2, Cloudflare Pay Per Crawl are still being
    17	 * finalized), so the broker never parses them. Draft-caveat discipline:
    18	 * build against the interface, not a draft's field names.
    19	 */
    20	export interface RailBackend extends PaymentRail {}
    21	
    22	/**
    23	 * In-memory rail for tests, demos, and local dev. Mirrors the x402 shape
    24	 * (micro-unit price, `X-PAYMENT` header) without an external service.
    25	 * Deterministic: with a `frozenClock` and fixed input, the settlement
    26	 * reference is stable so reconciliation can be asserted.
    27	 */
    28	export class InMemoryRail implements PaymentRail {
    29	  readonly id: string;
    30	  readonly priceMicros: Micros;
    31	  readonly currency: string;
    32	  readonly clock: Clock;
    33	  private readonly settlementSeed: string = '';
    34	  private readonly failureMode: 'none' | 'quote' | 'authorize' | 'settle';
    35	
    36	  constructor(options: {
    37	    id: string;
    38	    priceMicros: Micros;
    39	    currency?: string;
    40	    clock?: Clock;
    41	    failureMode?: 'none' | 'quote' | 'authorize' | 'settle';
    42	    /** Stable suffix seed so settlement refs are deterministic in tests. */
    43	    settlementSeed?: string;
    44	  }) {
    45	    this.id = options.id;
    46	    this.priceMicros = options.priceMicros;
    47	    this.currency = options.currency ?? 'USD';
    48	    this.clock = options.clock ?? { now: () => new Date().toISOString() };
    49	    this.failureMode = options.failureMode ?? 'none';
    50	    this.settlementSeed = options.settlementSeed ?? `${options.id}-seed`;
    51	  }
    52	
    53	  quote(_req: PaymentRequest): Promise<Quote> {
    54	    if (this.failureMode === 'quote') {
    55	      return Promise.reject(
    56	        new RailError(`${this.id}: quote failed`, 'RAIL_QUOTE', undefined, true)
    57	      );
    58	    }
    59	    const nowMs = Date.parse(this.clock.now());
    60	    return Promise.resolve({
    61	      unitsMicros: this.priceMicros,
    62	      currency: this.currency,
    63	      rail: this.id,
    64	      settlement: 'immediate',
    65	      expiresAt: new Date(nowMs + 60_000).toISOString(),
    66	    });
    67	  }
    68	
    69	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
    70	    if (this.failureMode === 'authorize') {
    71	      return Promise.reject(
    72	        new RailError(`${this.id}: authorize failed`, 'RAIL_AUTHORIZE', undefined, true)
    73	      );
    74	    }
    75	    const payload = JSON.stringify({
    76	      schema: 'urn:rail:' + this.id,
    77	      amountMicros: quote.unitsMicros,
    78	      currency: quote.currency,
    79	      url: String(req.url),
    80	      method: req.method,
    81	    });
    82	    return Promise.resolve({
    83	      scheme: this.id,
    84	      payload,
    85	      settlementHeaders: { [`${this.id.replace(/[^a-z0-9]/gi, '-').toLowerCase()}-payment`]: 'authorized' },
    86	    });
    87	  }
    88	
    89	  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
    90	    if (this.failureMode === 'settle') {
    91	      return Promise.reject(
    92	        new RailError(`${this.id}: settle failed`, 'RAIL_SETTLE', undefined, true)
    93	      );
    94	    }
    95	    const parsed = JSON.parse(authorization.payload) as { amountMicros: number; currency: string };
    96	    return Promise.resolve({
    97	      rail: this.id,
    98	      // Deterministic from (seed, url) so tests can assert reconciliation.
    99	      settlementRef: makeSettlementRef(this.id, deterministicRand(this.settlementSeed + String(req.url))),
   100	      amountMicros: parsed.amountMicros,
   101	      currency: parsed.currency,
   102	      settledAt: this.clock.now(),
   103	    });
   104	  }
   105	}
   106	
   107	/**
   108	 * Wraps an existing bridge client (e.g. an ap2-x402-bridge or AP2
   109	 * rail-adapter-x402 instance) so it can be used as a rail. The broker sees
   110	 * only this minimal shape — it does not depend on the bridge's own types.
   111	 * That is the "one contract" boundary in practice.
   112	 */
   113	export interface BridgeClientShape {
   114	  quote(input: { url: string; method: string; headers: Record<string, string> }): Promise<Quote>;
   115	  authorize(input: {
   116	    url: string;
   117	    method: string;
   118	    headers: Record<string, string>;
   119	    quote: { unitsMicros: number; currency: string };
   120	  }): Promise<RailAuthorization>;
   121	  settle(input: {
   122	    url: string;
   123	    method: string;
   124	    headers: Record<string, string>;
   125	    authorization: RailAuthorization;
   126	  }): Promise<RailSettlement>;
   127	}
   128	
   129	export class BridgeRail implements PaymentRail {
   130	  constructor(
   131	    private readonly idAndBridge: { id: string; bridge: BridgeClientShape }
   132	  ) {}
   133	
   134	  get id(): string {
   135	    return this.idAndBridge.id;
   136	  }
   137	
   138	  quote(req: PaymentRequest): Promise<Quote> {
   139	    return this.idAndBridge.bridge.quote({ url: String(req.url), method: req.method, headers: req.headers });
   140	  }
   141	
   142	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
   143	    return this.idAndBridge.bridge.authorize({
   144	      url: String(req.url),
   145	      method: req.method,
   146	      headers: req.headers,
   147	      quote: { unitsMicros: quote.unitsMicros, currency: quote.currency },
   148	    });
   149	  }
   150	
   151	  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
   152	    return this.idAndBridge.bridge.settle({
   153	      url: String(req.url),
   154	      method: req.method,
   155	      headers: req.headers,
   156	      authorization,
   157	    });
   158	  }
   159	}
   160	
   161	/** Registry lets the broker pick a rail per URL/tenant without touching the agent. */
   162	export class RailRegistry {
   163	  private readonly rails = new Map<string, PaymentRail>();
   164	
   165	  register(rail: PaymentRail): this {
   166	    if (this.rails.has(rail.id)) {
   167	      throw new RailError(`Rail already registered: ${rail.id} (deregister first)`, 'RAIL_REGISTER');
   168	    }
   169	    this.rails.set(rail.id, rail);
   170	    return this;
   171	  }
   172	
   173	  deregister(id: string): boolean {
   174	    return this.rails.delete(id);
   175	  }
   176	
   177	  get(id: string): PaymentRail {
   178	    const r = this.rails.get(id);
   179	    if (!r) throw new RailError(`No rail registered: ${id}`, 'RAIL_MISSING');
   180	    return r;
   181	  }
   182	
   183	  /** Look up a rail by id without throwing when it is absent. */
   184	  optional(id: string): PaymentRail | undefined {
   185	    return this.rails.get(id);
   186	  }
   187	
   188	  ids(): string[] {
   189	    return [...this.rails.keys()].sort();
   190	  }
   191	}
   192	
   193	/** Deterministic PRNG from a seed (FNV-1a based) so settlement refs are stable in tests. */
   194	function deterministicRand(seed: string): () => number {
   195	  let h = 2166136261;
   196	  for (let i = 0; i < seed.length; i++) {
   197	    h ^= seed.charCodeAt(i);
   198	    h = Math.imul(h, 16777619);
   199	  }
   200	  return () => {
   201	    h += 0x6d2b79f5;
   202	    let t = h;
   203	    t = Math.imul(t ^ (t >>> 15), t | 1);
   204	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
   205	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
   206	  };
   207	}"}

