     2	 * Self-hosted 402 settlement backend.
     3	 *
     4	 * The metered path (see `packages/gateway/src/broker.ts`) is:
     5	 *
     6	 *   rail.quote -> rail.authorize -> rail.settle -> origin.fetch(...)
     7	 *
     8	 * The rail's `settle` step is the payment commit. Previously `SelfHosted402Rail`
     9	 * only extended the in-memory stub, so a "self 402" never actually minted a
    10	 * proof, rejected a reused proof, or recorded a final receipt. This module
    11	 * makes it real:
    12	 *
    13	 *   1. The broker signs an Ed25519 **payment mandate** (a spend authorization)
    14	 *      over an opaque manifest, carrying a per-request nonce.
    15	 *   2. The rail POSTs that signed mandate to a settlement backend. The backend
    16	 *      verifies the signature, rejects a **replayed** nonce, signs a chained
    17	 *      settlement **receipt**, and returns it. A replayed proof throws
    18	 *      `RAIL_REPLAY` (non-retryable) — the broker maps a settle fault to
    19	 *      `payment-required`, exactly as an origin that still demanded payment.
    20	 *   3. The receipt lands in a small, Ed25519-**chained, tamper-evident ledger**
    21	 *      that the audit/`reconcile` surface can read.
    22	 *
    23	 * The wire form is intentionally minimal (draft-caveat: build against the
    24	 * *pattern* of x402's `PAYMENT-SIGNATURE`/`X-PAYMENT`, not its field names).
    25	 * The same backend runs in-process (tests, dev) or behind a thin HTTP service
    26	 * (`SettlementHttpServer`) on a separate host (`HttpSettlementClient`), so the
    27	 * rail needs no compile-time knowledge of where the backend lives.
    28	 *
    29	 * Crypto mirrors `packages/identity/src/ring.ts`: Ed25519 over a JWK, and the
    30	 * broker's own `b64url`/`fromB64url` from `@mwb/core`. No new dependency.
    31	 */
    32	
    33	import {
    34	  generateKeyPairSync,
    35	  sign,
    36	  verify,
    37	  createPrivateKey,
    38	  createPublicKey,
    39	  randomBytes,
    40	} from 'node:crypto';
    41	import {
    42	  RailError,
    43	  systemClock,
    44	  b64url,
    45	  fromB64url,
    46	  type Clock,
    47	  type PaymentRail,
    48	  type PaymentRequest,
    49	  type Quote,
    50	  type RailAuthorization,
    51	  type RailSettlement,
    52	  type Micros,
    53	} from '@mwb/core';
    54	
    55	/** The opaque mandate type the broker mints. Not a draft's field set. */
    56	const PAYMENT_MANDATE_TYPE = 'urn:mwb:self402:payment-mandate:v1';
    57	
    58	/** Fixed key order so the manifest bytes are byte-identical at sign and verify. */
    59	const MANDATE_FIELDS = [
    60	  'origin',
    61	  'url',
    62	  'amountMicros',
    63	  'currency',
    64	  'nonce',
    65	  'issuedAt',
    66	  'recipient',
    67	] as const;
    68	
    69	/** Accept a mandate whose `issuedAt` is within this window of the clock. */
    70	const ACCEPTANCE_WINDOW_MS = 5 * 60 * 1000;
    71	
    72	/** The header the rail injects on the settled origin request (holds the proof). */
    73	export const PAYMENT_HEADER = 'x-payment';
    74	
    75	/** An Ed25519 spend-authorizer. `privateKey` never leaves the signing side. */
    76	export interface SettlementKey {
    77	  keyId: string;
    78	  algorithm: 'ed25519';
    79	  /** 32-byte public key, JWK `x`, base64url. Shares the verifier. */
    80	  publicKey: string;
    81	  /** 32-byte seed, JWK `d`, base64url. Never leaves the broker. */
    82	  privateKey: string;
    83	  createdAt: string;
    84	}
    85	
    86	/** Mint a settlement key (broker's spend authorizer). */
    87	export function makeSettlementKey(
    88	  clock: Clock = systemClock,
    89	  keyId = `settle_${clock.now().replace(/[^A-Za-z0-9]/g, '')}`,
    90	): SettlementKey {
    91	  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
    92	  const pub = publicKey.export({ format: 'jwk' }) as { x?: string };
    93	  const priv = privateKey.export({ format: 'jwk' }) as { d?: string };
    94	  if (!pub.x || !priv.d) {
    95	    throw new RailError('failed to export Ed25519 JWK', 'SETTLEMENT_KEY');
    96	  }
    97	  return {
    98	    keyId,
    99	    algorithm: 'ed25519',
   100	    publicKey: b64url(fromB64url(pub.x)),
   101	    privateKey: b64url(fromB64url(priv.d)),
   102	    createdAt: clock.now(),
   103	  };
   104	}
   105	
   106	function privateKeyObject(k: SettlementKey): ReturnType<typeof createPrivateKey> {
   107	  return createPrivateKey({
   108	    format: 'jwk',
   109	    key: { kty: 'OKP', crv: 'Ed25519', d: k.privateKey, x: k.publicKey },
   110	  });
   111	}
   112	
   113	function publicKeyObject(k: SettlementKey): ReturnType<typeof createPublicKey> {
   114	  return createPublicKey({
   115	    format: 'jwk',
   116	    key: { kty: 'OKP', crv: 'Ed25519', x: k.publicKey },
   117	  });
   118	}
   119	
   120	function signBytes(k: SettlementKey, buf: Buffer): string {
   121	  return b64url(new Uint8Array(sign(null, buf, privateKeyObject(k))));
   122	}
   123	
   124	function verifyBytes(k: SettlementKey, buf: Buffer, sigB64: string): boolean {
   125	  try {
   126	    return verify(null, buf, publicKeyObject(k), Buffer.from(fromB64url(sigB64)));
   127	  } catch {
   128	    return false;
   129	  }
   130	}
   131	
   132	/** The signed spend authorization the broker mints and the rail commits. */
   133	export interface PaymentMandateManifest {
   134	  origin: string;
   135	  url: string;
   136	  amountMicros: number;
   137	  currency: string;
   138	  nonce: string;
   139	  issuedAt: string;
   140	  recipient: string;
   141	}
   142	
   143	export interface PaymentMandate extends PaymentMandateManifest {
   144	  /**
   145	   * 64-byte Ed25519 signature, base64url-encoded (86 chars, no padding). The
   146	   * wire form always sets it, but a hand-edited/tampered mandate may omit it.
   147	   */
   148	  signature?: string;
   149	}
   150	
   151	function manifestBytes(m: PaymentMandateManifest): Buffer {
   152	  const obj: Record<string, number | string> = {};
   153	  for (const f of MANDATE_FIELDS) obj[f] = m[f];
   154	  return Buffer.from(JSON.stringify(obj), 'utf8');
   155	}
   156	
   157	/** Build (sign) a payment mandate. */
   158	export function buildMandate(o: {
   159	  origin: string;
   160	  url: string;
   161	  amountMicros: number;
   162	  currency: string;
   163	  recipient: string;
   164	  clock: Clock;
   165	  key: SettlementKey;
   166	  nonce?: string;
   167	  issuedAt?: string;
   168	}): PaymentMandate {
   169	  const nonce = o.nonce ?? randomBytes(32).toString('base64url');
   170	  const issuedAt = o.issuedAt ?? o.clock.now();
   171	  const manifest: PaymentMandateManifest = {
   172	    origin: o.origin,
   173	    url: o.url,
   174	    amountMicros: o.amountMicros,
   175	    currency: o.currency,
   176	    nonce,
   177	    issuedAt,
   178	    recipient: o.recipient,
   179	  };
   180	  return { ...manifest, signature: signBytes(o.key, manifestBytes(manifest)) };
   181	}
   182	
   183	export interface VerifyResult {
   184	  valid: boolean;
   185	  reason?: string;
   186	}
   187	
   188	/**
   189	 * Verify a mandate's signature, manifest, and acceptance window. Does not
   190	 * consume the nonce — the origin can call this to gate content release.
   191	 */
   192	export function verifyMandate(
   193	  m: PaymentMandate,
   194	  key: SettlementKey,
   195	  opts?: { nowMs?: number },
   196	): VerifyResult {
   197	  if (typeof m.signature !== 'string' || m.signature.length === 0) {
   198	    return { valid: false, reason: 'missing-signature' };
   199	  }
   200	  if (!verifyBytes(key, manifestBytes(m), m.signature)) {
   201	    return { valid: false, reason: 'signature-mismatch' };
   202	  }
   203	  const iat = Date.parse(m.issuedAt);
   204	  if (Number.isNaN(iat)) return { valid: false, reason: 'bad-issuedAt' };
   205	  const nowMs = opts?.nowMs ?? Date.now();
   206	  if (Math.abs(nowMs - iat) > ACCEPTANCE_WINDOW_MS) {
   207	    return { valid: false, reason: 'issued-out-of-window' };
   208	  }
   209	  if (!(m.amountMicros > 0)) return { valid: false, reason: 'non-positive-amount' };
   210	  return { valid: true };
   211	}
   212	
   213	/** A receipt minted by the backend, signed by its key. */
   214	export interface SettlementReceipt {
   215	  settlementRef: string;
   216	  origin: string;
   217	  url: string;
   218	  amountMicros: number;
   219	  currency: string;
   220	  nonce: string;
   221	  issuedAt: string;
   222	  settledAt: string;
   223	}
   224	
   225	/** One entry in the chained, tamper-evident settlement ledger. */
   226	export interface LedgerRecord {
   227	  seq: number;
   228	  receipt: SettlementReceipt;
   229	  signedAt: string;
   230	  /** Signature over `${seq}\0${ref}\0${previousSignature}`. */
   231	  signature: string;
   232	}
   233	
   234	/**
   235	 * The settlement backend: verifies signed mandates, enforces replay
   236	 * protection (a nonce is consumed exactly once), and records a final,
   237	 * cryptographically-chained receipt ledger. Runs in-process.
   238	 */
   239	export class SettlementServer {
   240	  readonly key: SettlementKey;
   241	  readonly clock: Clock;
   242	  private readonly consumed = new Set<string>();
   243	  private readonly ledgerRows: LedgerRecord[] = [];
   244	
   245	  constructor(options: { key: SettlementKey; clock?: Clock }) {
   246	    this.key = options.key;
   247	    this.clock = options.clock ?? systemClock;
   248	  }
   249	
   250	  /** Pure: is this mandate's signature valid and in-window? (No state change.) */
   251	  isValidMandate(m: PaymentMandate): boolean {
   252	    return verifyMandate(m, this.key, { nowMs: Date.parse(this.clock.now()) }).valid;
   253	  }
   254	
   255	  /** Verify and, on first use, consume the nonce, then mint a receipt. */
   256	  verify(m: PaymentMandate): VerifyResult {
   257	    const v = verifyMandate(m, this.key, { nowMs: Date.parse(this.clock.now()) });
   258	    if (!v.valid) return v;
   259	    if (this.consumed.has(m.nonce)) {
   260	      return { valid: false, reason: 'replayed-proof' };
   261	    }
   262	    return { valid: true };
   263	  }
   264	
   265	  /**
   266	   * The payment commit. Verifies, rejects a replayed nonce (throwing
   267	   * `RAIL_REPLAY`, non-retryable), records a chained receipt, and returns the
   268	   * `RailSettlement` the broker surfaces on a fulfilled outcome.
   269	   */
   270	  settle(m: PaymentMandate): RailSettlement {
   271	    const v = this.verify(m);
   272	    if (!v.valid) {
   273	      throw new RailError(
   274	        `settlement rejected: ${v.reason ?? 'unknown'}`,
   275	        'RAIL_SETTLE',
   276	        undefined,
   277	        false,
   278	      );
   279	    }
   280	    const settledAt = this.clock.now();
   281	    const settlementRef = `settle_self402_${randomBytes(9).toString('hex')}`;
   282	    const receipt: SettlementReceipt = {
   283	      settlementRef,
   284	      origin: m.origin,
   285	      url: m.url,
   286	      amountMicros: m.amountMicros,
   287	      currency: m.currency,
   288	      nonce: m.nonce,
   289	      issuedAt: m.issuedAt,
   290	      settledAt,
   291	    };
   292	    const prevSig = this.ledgerRows.length > 0 ? this.ledgerRows[this.ledgerRows.length - 1]!.signature : 'genesis';
   293	    const seq = this.ledgerRows.length + 1;
   294	    const chain = Buffer.from(`${seq}\u0000${receipt.settlementRef}\u0000${prevSig}`, 'utf8');
   295	    const signature = signBytes(this.key, chain);
   296	    this.ledgerRows.push({ seq, receipt, signedAt: settledAt, signature });
   297	    this.consumed.add(m.nonce);
   298	    return {
   299	      rail: 'self402',
   300	      settlementRef,
   301	      amountMicros: m.amountMicros,
   302	      currency: m.currency,
   303	      settledAt,
   304	    };
   305	  }
   306	
   307	  /** The current settlement ledger (a copy) — surfaced on the audit view. */
   308	  ledger(): LedgerRecord[] {
   309	    return this.ledgerRows.map((r) => ({ ...r, receipt: { ...r.receipt } }));
   310	  }
   311	
   312	  /** How many distinct nonces have been settled (== ledger length). */
   313	  settledCount(): number {
   314	    return this.ledgerRows.length;
   315	  }
   316	}
   317	
   318	/**
   319	 * A `PaymentRail` backed by a settlement backend (in-process
   320	 * `SettlementServer`, or a remote `HttpSettlementClient`). The rail signs the
   321	 * mandate (with the broker's key) and commits it via the backend. Spec-agnostic
   322	 * — the broker only sees `quote/authorize/settle`.
   323	 */
   324	export class SelfHosted402Rail implements PaymentRail {
   325	  readonly id = 'self402';
   326	
   327	  constructor(
   328	    private readonly backend: SettlementBackend,
   329	    private readonly key: SettlementKey,
   330	    private readonly opts: {
   331	      priceMicros: Micros;
   332	      currency?: string;
   333	      clock?: Clock;
   334	      origin?: string;
   335	    },
   336	  ) {}
   337	
   338	  async quote(_req: PaymentRequest): Promise<Quote> {
   339	    const nowMs = Date.parse(this.opts.clock?.now() ?? systemClock.now());
   340	    return {
   341	      unitsMicros: this.opts.priceMicros,
   342	      currency: this.opts.currency ?? 'USD',
   343	      rail: this.id,
   344	      settlement: 'immediate',
   345	      expiresAt: new Date(nowMs + 60_000).toISOString(),
   346	    };
   347	  }
   348	
   349	  async authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization> {
   350	    const origin = this.opts.origin ?? new URL(String(req.url)).origin;
   351	    const mandate = buildMandate({
   352	      origin,
   353	      url: String(req.url),
   354	      amountMicros: quote.unitsMicros,
   355	      currency: this.opts.currency ?? 'USD',
   356	      recipient: this.key.keyId,
   357	      clock: this.opts.clock ?? systemClock,
   358	      key: this.key,
   359	    });
   360	    const xPayment = encodeXPayment(mandate);
   361	    return {
   362	      scheme: this.id,
   363	      payload: JSON.stringify(mandate),
   364	      settlementHeaders: { [PAYMENT_HEADER]: xPayment },
   365	    };
   366	  }
   367	
   368	  async settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement> {
   369	    const mandate = JSON.parse(authorization.payload) as PaymentMandate;
   370	    if (mandate.url !== String(req.url)) {
   371	      throw new RailError('settlement mandate does not match the request', 'RAIL_SETTLE');
   372	    }
   373	    return this.backend.settle(mandate);
   374	  }
   375	}
